   264  M3Result  EvaluateExpression  (IM3Module i_module, void * o_expressed, u8 i_type, bytes_t * io_bytes, cbytes_t i_end)
   265  {
   266      M3Result result = m3Err_none;
   267
   268      // create a temporary runtime context
   269  #if defined(d_m3PreferStaticAlloc)
   270      static M3Runtime runtime;
   271  #else
   272      M3Runtime runtime;
   273  #endif
   274      M3_INIT (runtime);
   275
   276      runtime.environment = i_module->runtime->environment;
   277      runtime.numStackSlots = i_module->runtime->numStackSlots;
   278      runtime.stack = i_module->runtime->stack;
   279
   280      m3stack_t stack = (m3stack_t)runtime.stack;
   281
   282      IM3Runtime savedRuntime = i_module->runtime;
   283      i_module->runtime = & runtime;
   284
   285      IM3Compilation o = & runtime.compilation;
   286      o->runtime = & runtime;
   287      o->module =  i_module;
   288      o->wasm =    * io_bytes;
   289      o->wasmEnd = i_end;
   290      o->lastOpcodeStart = o->wasm;
   291
   292      o->block.depth = -1;  // so that root compilation depth = 0
   293
   294      //  OPTZ: this code page could be erased after use.  maybe have 'empty' list in addition to full and open?
   295      o->page = AcquireCodePage (& runtime);  // AcquireUnusedCodePage (...)
   296
   297      if (o->page)
   298      {
   299          IM3FuncType ftype = runtime.environment->retFuncTypes[i_type];
   300
   301          pc_t m3code = GetPagePC (o->page);
   302          result = CompileBlock (o, ftype, c_waOp_block);
   303
   304          if (not result)
   305          {
   306              m3ret_t r = Call (m3code, stack, NULL, d_m3OpDefaultArgs);
   307
   308              if (r == 0)
   309              {
   310                  if (SizeOfType (i_type) == sizeof (u32))
   311                  {
   312                      * (u32 *) o_expressed = * ((u32 *) stack);
   313                  }
   314                  else
   315                  {
   316                      * (u64 *) o_expressed = * ((u64 *) stack);
   317                  }
   318              }
   319          }
   320
   321          // TODO: EraseCodePage (...) see OPTZ above
   322          ReleaseCodePage (& runtime, o->page);
   323      }
   324      else result = m3Err_mallocFailedCodePage;
   325
   326      runtime.stack = NULL;        // prevent free(stack) in ReleaseRuntime
   327      Runtime_Release (& runtime);
   328      i_module->runtime = savedRuntime;
   329
   330      * io_bytes = o->wasm;
   331
   332      return result;
   333  }
